8. 
9. @if (isLoading)
10. {
11.     <p class="loading">Loading tasks...</p>
12. }
13. else if (errorMessage is not null)
14. {
15.     <p class="error">@errorMessage</p>
16. }
17. else
18. {
19.     <BoardStatsBar Total="allTasks.Count"
20.                    ToDo="GetTasksByStatus("To Do").Count"
